internal static class Psychic025Tests {
 static int n;static float distance;static UnitEntityData owner,other;static EntityFactsManager facts;
 static T Empty<T>()where T:class=>(T)FormatterServices.GetUninitializedObject(typeof(T));static object Get(object o,string s)=>AccessTools.Field(o.GetType(),s).GetValue(o);static void Set(object o,string s,object v)=>AccessTools.Field(o.GetType(),s).SetValue(o,v);static void Check(bool b,string s){if(!b)throw new Exception("025 repair: "+s);n++;}
 static T Asset<T>(BlueprintsCache c,string token)where T:SimpleBlueprint=>(T)c.Load((BlueprintGuid)AccessTools.Method(typeof(PsychicEtherPenalty).Assembly.GetType("CallOfTheWild.Wrath.Prototype.PsychicAssets"),"Id").Invoke(null,new object[]{token}));
 static void Refresh()=>AccessTools.Method(Get(facts,"m_Cache").GetType(),"Clear").Invoke(Get(facts,"m_Cache"),null);static void Clear(){facts.List.Clear();Refresh();}
 static void Setup(UnitEntityData u){var fs=new EntityFactsManager(u);Set(u,"Facts",fs);var bc=new BuffCollection();bc.Initialize(fs);Set(u,"<Buffs>k__BackingField",bc);Set(u.State.Features,"Flying",new CountableFlag());Set(u.State,"m_Conditions",new sbyte[128]);Set(u.State,"m_ConditionsImmunity",new sbyte[128]);Set(u.State,"m_ConditionsExceptions",new List<UnitConditionExceptions>[128]);}
 static MechanicsContext Context(BlueprintScriptableObject bp){var c=new MechanicsContext(owner,owner.Descriptor,bp,null,new TargetWrapper(owner));c.SetParams(new Kingmaker.UnitLogic.Abilities.AbilityParams {CasterLevel=12,DC=23,SpellLevel=5});return c;}
 static Buff NativeFact(BlueprintBuff bp){var b=Empty<Buff>();Set(b,"Components",new List<EntityFactComponent>());b.RestoreOwnerLink(facts);Set(b,"m_Context",Context(bp));Set(b,"<Rank>k__BackingField",1);AccessTools.Method(typeof(EntityFact),"Setup").Invoke(b,new object[]{bp});Set(b,"<IsActive>k__BackingField",true);Set(b,"<IsTurnedOn>k__BackingField",true);facts.List.Add(b);Refresh();return b;}
 internal static int Run(BlueprintsCache c){owner=new Psychic070Tests.Caster(c).Unit;other=new Psychic070Tests.Caster(c).Unit;Setup(owner);Setup(other);facts=owner.Facts;var speed=new ModifiableValueSpeed(owner.Stats);Set(owner.Stats,"Speed",speed);owner.Stats.AllStats.Add(speed);speed.BaseValue=30;var h=new Harmony("CotW025.Repairs");h.Patch(AccessTools.Method(typeof(UnitEntityData),"DistanceTo",new[]{typeof(UnitEntityData)}),prefix:new HarmonyMethod(typeof(Psychic025Tests),nameof(Distance)));
 try{Construction(c);Flight(c);Ether(c,h);Ground(c,h);Visuals(c);}finally{h.UnpatchAll(h.Id);Clear();}PsychicExpansionTests.Inventory["repair025Assertions"]=n;Console.WriteLine("PASS: "+n+" repair checks: native EntityFact.Setup/name identity/save dictionary, native flight counters and speed, rule subscriber dispatch, installed ether percentile/ground hooks, owned FX graph. Scene endpoints not rendered.");return n;}
 static bool Distance(ref float __result){__result=distance;return false;}
 static void Construction(BlueprintsCache c){foreach(string token in new[]{"CondensedEtherBuff","BarrowHazeBuff","BarrowHazeFog","ObscuringMistBuff","FogCloudBuff","SolidFogFog","SleetStormFog","NativeFogCloudConcealmentBuff","AirWalkBuff","OverlandFlightBuff","FlamingSphereController","FlamingSphereGreaterController","AggressiveThundercloudController","AggressiveThundercloudGreaterController","BallLightningController"}){Clear();var bp=Asset<BlueprintBuff>(c,token);var f=NativeFact(bp);int expected=bp.ComponentsArray.Count(x=>x is IRuntimeEntityFactComponentProvider);Check(f.Components.Count==expected,"Real native Setup builds every runtime component: "+token);Check(f.Components.All(x=>!string.IsNullOrEmpty(x.SourceBlueprintComponentName))&&f.Components.Select(x=>x.SourceBlueprintComponentName).Distinct().Count()==expected,"Distinct persisted names: "+token);var dict=(IDictionary)AccessTools.Property(typeof(EntityFact),"ComponentsDictionary").GetValue(f);Check(dict.Count==expected,"Native save component dictionary accepts all names");}
 Clear();var fly=Asset<BlueprintBuff>(c,"OverlandFlightBuff");var names=fly.ComponentsArray.Select(x=>x.name).ToArray();try{foreach(var x in fly.ComponentsArray)x.name=null;var old=NativeFact(fly);Check(old.Components.Count==1,"Old unnamed flight graph independently reproduces skipped components");bool throws=false;try{AccessTools.Property(typeof(EntityFact),"ComponentsDictionary").GetValue(old);}catch(System.Reflection.TargetInvocationException e){throws=e.InnerException is ArgumentNullException;}Check(throws,"Old unnamed fact cannot produce native save dictionary");}finally{for(int i=0;i<names.Length;i++)fly.ComponentsArray[i].name=names[i];Clear();}}
 static void Flight(BlueprintsCache c){foreach(string token in new[]{"AirWalkBuff","OverlandFlightBuff"}){Clear();var bp=Asset<BlueprintBuff>(c,token);var f=NativeFact(bp);int before=owner.Stats.Speed.ModifiedValue;foreach(var rt in f.Components.Where(x=>x.SourceBlueprintComponent is SpellImmunityToSpellDescriptor||x.SourceBlueprintComponent is AddMechanicsFeature||x.SourceBlueprintComponent is AddConditionImmunity||x.SourceBlueprintComponent is AddStatBonus))rt.TurnOn();Check(owner.State.Features.Flying,"Native named flight flag activated");Check((((sbyte[])Get(owner.State,"m_ConditionsImmunity"))[(int)UnitCondition.DifficultTerrain]>0),"Native condition immunity activated");Check(owner.Stats.Speed.ModifiedValue==before+(token=="OverlandFlightBuff"?10:0),"Native speed modifier adds10 only Overland");Check(owner.Get<UnitPartSpellResistance>().Immunities.Any(x=>x.SpellDescriptor.HasAnyFlag(SpellDescriptor.Ground)),"Native Ground immunity registered");
 var comp=bp.GetComponent<BuffDescriptorImmunity>();var runtime=f.Components.Single(x=>x.SourceBlueprintComponent==comp);foreach(bool ground in new[]{false,true}){var ctx=Context(bp);Set(ctx,"<SpellDescriptor>k__BackingField",ground?SpellDescriptor.Ground:SpellDescriptor.Fire);var rule=new RuleCanApplyBuff(owner,new BlueprintBuff {ComponentsArray=Array.Empty<BlueprintComponent>()},ctx,null);using(runtime.RequestEventContext())comp.OnEventAboutToTrigger(rule);Check(rule.Immunity==ground,"Native ground buff rejection, non-ground preserved");}
 foreach(var rt in f.Components.AsEnumerable().Reverse())if(rt.IsTurnedOn)rt.TurnOff();Check(!owner.State.Features.Flying&&!(((sbyte[])Get(owner.State,"m_ConditionsImmunity"))[(int)UnitCondition.DifficultTerrain]>0)&&owner.Stats.Speed.ModifiedValue==before,"Native expiry cleanup releases flags and speed: "+token+" fly="+owner.State.Features.Flying+" immune="+((sbyte[])Get(owner.State,"m_ConditionsImmunity"))[(int)UnitCondition.DifficultTerrain]+" speed="+owner.Stats.Speed.ModifiedValue+" before="+before);Check(!(owner.Get<UnitPartSpellResistance>()?.Immunities.Any(x=>x.SpellDescriptor.HasAnyFlag(SpellDescriptor.Ground))??false),"Source Ground immunity removed");}
 Clear();}
 static void Ether(BlueprintsCache c,Harmony h){Clear();var b=NativeFact(Asset<BlueprintBuff>(c,"CondensedEtherBuff"));var bp=b.Blueprint;Check(!bp.GetComponents<AddConcealment>().Any()&&bp.GetComponent<PsychicOutgoingFog>()==null,"Ether supplies no optical concealment");foreach(var rt in b.Components.Where(x=>x.SourceBlueprintComponent is PsychicEtherPenalty||x.SourceBlueprintComponent is PsychicWeatherMiss))rt.TurnOn();AccessTools.Method(typeof(EntityFact),"Subscribe").Invoke(b,null);
 try{var ac=new RuleCalculateAC(other,owner,AttackType.Melee);RulebookEventBus.OnEventAboutToTrigger(ac);Check(ac.AllBonuses.Sum(x=>x.Value)==-2,"Native subscribed AC callback, no manual component call");foreach(var type in new[]{SavingThrowType.Reflex,SavingThrowType.Will,SavingThrowType.Fortitude}){var save=new RuleSavingThrow(owner,type,20);RulebookEventBus.OnEventAboutToTrigger(save);Check(save.AllBonuses.Sum(x=>x.Value)==(type==SavingThrowType.Reflex?-2:0),"Native subscribed Reflex-only penalty");}}finally{AccessTools.Method(typeof(EntityFact),"Unsubscribe").Invoke(b,null);}
 var patch=typeof(PsychicEtherPenalty).Assembly.GetType("CallOfTheWild.Wrath.Prototype.PsychicEtherMissPatch");h.CreateClassProcessor(patch).Patch();var method=AccessTools.Method(typeof(RuleAttackRoll),"TryOvercomeTargetConcealmentAndMissChance");var q=(Queue<int>)GetStatic(typeof(Psychic070Tests),"dice");
 foreach(float feet in new[]{1f,5f,5.1f,30f})foreach(int rolled in new[]{1,20,21,50,51,100})foreach(bool outgoing in new[]{false,true}){distance=new Feet(feet).Meters;var rule=new RuleAttackRoll(outgoing?owner:other,outgoing?other:owner,(Kingmaker.Items.ItemEntityWeapon)AccessTools.Method(typeof(PsychicWeatherTests),"Weapon").Invoke(null,new object[]{AttackType.RangedTouch}),0){IgnoreConcealment=true};q.Enqueue(rolled);bool pass=(bool)method.Invoke(rule,null);Check(pass==(rolled>(feet>5?50:20)),"Independent percentile unaffected by IgnoreConcealment; incoming/outgoing boundary");Check(rule.MissChanceValue==(feet>5?50:20)&&rule.MissChanceRoll!=null&&q.Count==0,"Exactly one independent roll and combat-log diagnostics");}
 Clear();distance=100;var clean=new RuleAttackRoll(owner,other,(Kingmaker.Items.ItemEntityWeapon)AccessTools.Method(typeof(PsychicWeatherTests),"Weapon").Invoke(null,new object[]{AttackType.RangedTouch}),0){IgnoreConcealment=true};Check((bool)method.Invoke(clean,null)&&clean.MissChanceRoll==null,"No ether has no extra roll");}
 static object GetStatic(Type t,string s)=>AccessTools.Field(t,s).GetValue(null);
 static void Ground(BlueprintsCache c,Harmony h){var type=typeof(PsychicEtherPenalty).Assembly.GetType("CallOfTheWild.Wrath.Prototype.PsychicFlightGroundPatch");h.CreateClassProcessor(type).Patch();var method=AccessTools.Method(typeof(AreaEffectEntityData),"IsSuitableTargetType");h.Patch(method,prefix:new HarmonyMethod(typeof(Psychic025Tests),nameof(Geometry)){priority=Priority.Last});
 foreach(string flight in new[]{"AirWalkBuff","OverlandFlightBuff"})foreach(int kind in new[]{0,1,2,3,4,5})foreach(bool active in new[]{false,true}){Clear();var f=NativeFact(Asset<BlueprintBuff>(c,flight));Set(f,"<IsTurnedOn>k__BackingField",active);var area=Empty<AreaEffectEntityData>();var bp=new BlueprintAbilityAreaEffect {ComponentsArray=kind==4?new BlueprintComponent[]{new AreaEffectPit()}:Array.Empty<BlueprintComponent>(),AssetGuid=BlueprintGuid.Parse(kind==1?"16e0e4c6a16f68c49832340b93706499":kind==2?"eca936a9e235875498d1e74ff7c09ecd":kind==3?"8b4ea698ae053c541beed4e050f32dc3":"dddddddddddddddddddddddddddddddd")};Set(area,"m_Blueprint",bp);var ctx=Context(bp);Set(ctx,"<SpellDescriptor>k__BackingField",kind==0?SpellDescriptor.Ground:SpellDescriptor.None);Set(area,"m_Context",ctx);Check((bool)method.Invoke(area,new object[]{owner})==(!active||kind==5),"Installed scoped ground/pit/spikes exclusion with native geometry boundary");}Clear();}
 static bool Geometry(ref bool __result){__result=true;return false;}
 static void Visuals(BlueprintsCache c){foreach(string token in new[]{"FlamingSphere","FlamingSphereGreater","AggressiveThundercloud","AggressiveThundercloudGreater","BallLightning"}){var a=Asset<BlueprintAbility>(c,token);var area=Asset<BlueprintAbilityAreaEffect>(c,token+"Area");Check(!a.GetComponents<AbilitySpawnFx>().Any(),"Loop prefab cannot enter unowned cast FX path");Check(!string.IsNullOrEmpty(area.Fx.AssetId),"Single persistent visual retained on owned area");Check(area.GetComponent<UniqueAreaEffect>().Feature==Asset<BlueprintBuff>(c,token+"Controller"),"Native unique area ownership preserved");Check(!Asset<BlueprintAbility>(c,token+"Move").GetComponents<AbilitySpawnFx>().Any(),"Move cannot create unowned FX");}}
